def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)
    with io.open(os.path.join(root, SEEDER_PATH), encoding="utf-8") as f:
        seeder = f.read()

    if "honest_counter" in data:
        print("Already applied. Nothing to do.")
        return
    if '"3.151.0"' not in init:
        sys.exit("ABORT: not at v3.151.0.")

    old_order = 'ORDER = ["counter_system", "pos_profile", "terminal_estate", "shift_sale", "concessions_returns", "extended_counters", "voucher_programme"]'
    new_order = 'ORDER = ["counter_system", "pos_profile", "terminal_estate", "shift_sale", "concessions_returns", "extended_counters", "voucher_programme", "honest_counter"]'
    if seeder.count(old_order) != 1:
        sys.exit(f"ABORT: seeder ORDER anchor not found exactly once ({seeder.count(old_order)}).")

    problems = []
    if len(LESSONS) != 10:
        problems.append(f"  {len(LESSONS)} lessons (want 10 — the track's second deep module)")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in LESSONS if len(l["html"]) < 2500]
    if short:
        problems.append(f"  below manual depth: {short}")
    if len(QUESTIONS) != 35:
        problems.append(f"  {len(QUESTIONS)} questions (want 35)")
    for q in QUESTIONS:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": LESSONS, "q": QUESTIONS}):
        problems.append("  ERPNext branding leakage")
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — spread failed: {dist}")
        sys.exit(1)

    total = sum(len(l["html"]) for l in LESSONS)
    print(f"POS 8: 10 chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["honest_counter"] = {
        "title": "POS 8 — The Honest Counter",
        "desc": "The track's second deep module and its proof: offline as a designed mode with the server-verification boundary, the chips and the queue worked to zero, conflicts and failed sales as money that has not landed, the fast-checkout judgment, End of Day Funds and the daily ritual, the cashier fraud map at full depth with the supervisor's weekly hour, the housekeeping calendar and lifecycle events, the handover test and the owner's five-line page — supervision living in structure, closing the ZhiftPOS Professional track.",
        "lessons": LESSONS,
        "questions": bank,
    }
    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, SEEDER_PATH), "w", encoding="utf-8") as f:
        f.write(seeder.replace(old_order, new_order, 1))
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.151.0"', '"3.152.0"'))
    print("  data: POS 8 appended; seeder ORDER extended — ZPOS-PRO COMPLETE (8 modules)")
    print("wrote __version__ -> 3.152.0")


if __name__ == "__main__":
    main()
